INSERT INTO ngos (ngo_id, slug, name, description, long_description, website, email, phone, logo_url, social_links, founded_year, state_id, city, address, pincode, registration_number, is_80g, is_12a, is_fcra, is_verified, listing_status, volunteer_available, internship_available, donation_available, accepts_csr, team_size, funding_type, beneficiaries_count, impact_score, last_verified_at, source_url) VALUES ('KER001', 'thanal', 'Thanal', 'Thanal is Kerala''s pioneering environmental organisation working on pesticide safety, organic farming, biodiversity conservation, and environmental health.', 'Thanal is Kerala''s pioneering environmental organisation working on pesticide safety, organic farming, biodiversity conservation, and environmental health. It led the national campaign against endosulfan in Kerala — a decade-long effort that resulted in a Supreme Court ban on the pesticide. Thanal continues to work on chemical safety, seed sovereignty, and the rights of farming communities affected by toxic agriculture.', 'https://thanal.co.in', 'thanal@thanal.co.in', '0471-2328937', 'https://thanal.co.in/favicon.ico', '{}'::jsonb, 1986, (SELECT id FROM states WHERE name = 'Kerala'), 'Thiruvananthapuram', 'Thiruvananthapuram, Kerala', '695001', 'Verify', 'Yes', 'Yes', 'No', TRUE, 'Active', TRUE, FALSE, TRUE, FALSE, '10-50', 'Grants + Donations', NULL, 7, '2025-06-01'::date, 'https://thanal.co.in') ON CONFLICT (ngo_id) DO NOTHING;
