INSERT INTO ngos (ngo_id, slug, name, description, long_description, website, email, phone, logo_url, social_links, founded_year, state_id, city, address, pincode, registration_number, is_80g, is_12a, is_fcra, is_verified, listing_status, volunteer_available, internship_available, donation_available, accepts_csr, team_size, funding_type, beneficiaries_count, impact_score, last_verified_at, source_url) VALUES ('PUN001', 'kheti-virasat-mission', 'Kheti Virasat Mission', 'Kheti Virasat Mission (KVM) leads Punjab''s natural farming movement, working with thousands of farmers to transition from chemical-intensive Green Revolution agriculture to sustainable, zero-budget natural farming.', 'Kheti Virasat Mission (KVM) leads Punjab''s natural farming movement, working with thousands of farmers to transition from chemical-intensive Green Revolution agriculture to sustainable, zero-budget natural farming. KVM''s work addresses Punjab''s water crisis, pesticide poisoning, and farmer debt crisis through practical demonstrations of chemical-free farming that match or exceed conventional yields. It also preserves indigenous seed varieties and traditional ecological knowledge.', 'https://khetivirasat.net', 'kvm@khetivirasat.net', '01635-223344', 'https://khetivirasat.net/favicon.ico', '{"twitter":"@KhetiVirasat","facebook":"KhetiVirasatMission"}'::jsonb, 2005, (SELECT id FROM states WHERE name = 'Punjab'), 'Jaitu', 'Jaitu, Punjab', '151202', 'Verify', 'Yes', 'Yes', 'No', TRUE, 'Active', TRUE, FALSE, TRUE, FALSE, '10-50', 'Donations + Grants', NULL, 7, '2025-06-01'::date, 'https://khetivirasat.net') ON CONFLICT (ngo_id) DO NOTHING;
