INSERT INTO ngos (ngo_id, slug, name, description, long_description, website, email, phone, logo_url, social_links, founded_year, state_id, city, address, pincode, registration_number, is_80g, is_12a, is_fcra, is_verified, listing_status, volunteer_available, internship_available, donation_available, accepts_csr, team_size, funding_type, beneficiaries_count, impact_score, last_verified_at, source_url) VALUES ('WOM001', 'sewa-self-employed-womens-association', 'SEWA – Self Employed Women''s Association', 'Trade union and NGO for self-employed women.', 'SEWA (Self Employed Women''s Association) is a trade union and NGO representing over 2 million self-employed women workers — street vendors, domestic workers, and home-based producers — across India. Through integrated services covering livelihoods, finance, healthcare, and legal aid, SEWA builds economic security for women at the bottom of the labour market. Its model of organising informal women workers has been replicated in over 18 countries.', 'https://sewa.org', 'mail@sewa.org', '079-25506477', 'https://sewa.org/favicon.ico', '{"twitter":"@SEWAIndia","linkedin":"sewa-india","instagram":"sewaindiaofficial","facebook":"sewaindiaorg"}'::jsonb, 1972, (SELECT id FROM states WHERE name = 'Gujarat'), 'Ahmedabad', 'Ahmedabad, Gujarat', '380001', 'Verify', 'Yes', 'Yes', 'No', TRUE, 'Active', TRUE, TRUE, TRUE, FALSE, '1000+', 'Self-sustaining + Grants', 2000000, 10, '2025-06-01'::date, 'https://sewa.org') ON CONFLICT (ngo_id) DO NOTHING;
INSERT INTO ngos (ngo_id, slug, name, description, long_description, website, email, phone, logo_url, social_links, founded_year, state_id, city, address, pincode, registration_number, is_80g, is_12a, is_fcra, is_verified, listing_status, volunteer_available, internship_available, donation_available, accepts_csr, team_size, funding_type, beneficiaries_count, impact_score, last_verified_at, source_url) VALUES ('WOM012', 'vimochana', 'Vimochana', 'Forum for women''s rights and anti-domestic violence.', 'Forum for women''s rights and anti-domestic violence, based in Bengaluru, Karnataka. The organisation runs programmes including legal aid for dv survivors, counseling, awareness campaigns, directly benefiting communities across the region. Volunteers and interns can engage through roles such as legal aid volunteer, counseling intern, campaign volunteer, gaining hands-on experience in women empowerment work.', 'https://vimochanaforum.org', 'vimochana@gmail.com', '080-25457284', 'https://vimochanaforum.org/favicon.ico', '{}'::jsonb, 1979, (SELECT id FROM states WHERE name = 'Karnataka'), 'Bengaluru', 'Bengaluru, Karnataka', '560001', 'Verify', 'Yes', 'Yes', 'Verify', TRUE, 'Active', TRUE, FALSE, TRUE, FALSE, '100-500', 'Grants + Donations', 15000, 6, '2025-06-01'::date, 'https://vimochanaforum.org') ON CONFLICT (ngo_id) DO NOTHING;
INSERT INTO ngos (ngo_id, slug, name, description, long_description, website, email, phone, logo_url, social_links, founded_year, state_id, city, address, pincode, registration_number, is_80g, is_12a, is_fcra, is_verified, listing_status, volunteer_available, internship_available, donation_available, accepts_csr, team_size, funding_type, beneficiaries_count, impact_score, last_verified_at, source_url) VALUES ('WOM009', 'sakhi-womens-resource-centre', 'Sakhi Women''s Resource Centre', 'Support services for women survivors of violence.', 'Support services for women survivors of violence, based in Thiruvananthapuram, Kerala. The organisation runs programmes including counseling for survivors, legal aid, safe shelter, directly benefiting communities across the region. Volunteers and interns can engage through roles such as counselor volunteer, legal aid intern, case worker, gaining hands-on experience in women empowerment work.', 'https://sakhicenter.org', 'sakhikerala@gmail.com', '0471-2572060', 'https://sakhicenter.org/favicon.ico', '{}'::jsonb, 1997, (SELECT id FROM states WHERE name = 'Kerala'), 'Thiruvananthapuram', 'Thiruvananthapuram, Kerala', '695001', 'Verify', 'Yes', 'Yes', 'Verify', TRUE, 'Active', TRUE, FALSE, TRUE, FALSE, '100-500', 'Grants + Donations', 20000, 6, '2025-06-01'::date, 'https://sakhicenter.org') ON CONFLICT (ngo_id) DO NOTHING;
INSERT INTO ngos (ngo_id, slug, name, description, long_description, website, email, phone, logo_url, social_links, founded_year, state_id, city, address, pincode, registration_number, is_80g, is_12a, is_fcra, is_verified, listing_status, volunteer_available, internship_available, donation_available, accepts_csr, team_size, funding_type, beneficiaries_count, impact_score, last_verified_at, source_url) VALUES ('WOM014', 'lijjat-papad', 'Lijjat Papad', 'Women''s livelihood through production cooperative.', 'Women''s livelihood through production cooperative, based in Mumbai, Maharashtra. The organisation runs programmes including women''s cooperative production, livelihood training, marketing support, directly benefiting communities across the region. Volunteers and interns can engage through roles such as production volunteer, marketing intern, quality checker, gaining hands-on experience in women empowerment work.', 'https://lijjat.com', 'info@lijjat.com', '022-23826691', 'https://lijjat.com/favicon.ico', '{}'::jsonb, 1959, (SELECT id FROM states WHERE name = 'Maharashtra'), 'Mumbai', 'Mumbai, Maharashtra', '400001', 'Verify', 'Yes', 'Yes', 'Verify', TRUE, 'Active', FALSE, FALSE, TRUE, FALSE, '100-500', 'Grants + Donations', 45000, 6, '2025-06-01'::date, 'https://lijjat.com') ON CONFLICT (ngo_id) DO NOTHING;
