-- ────────────────────────────────────────────────────────────
-- Verify counts after seeding
-- ────────────────────────────────────────────────────────────
SELECT
  (SELECT COUNT(*) FROM states)           AS state_count,
  (SELECT COUNT(*) FROM categories)       AS category_count,
  (SELECT COUNT(*) FROM ngos)             AS ngo_count,
  (SELECT COUNT(*) FROM ngo_categories)   AS ngo_category_links;

COMMIT;
